const item = $input.first();
const bin = item.binary && item.binary.data ? item.binary.data : undefined;

let size = undefined;

if (bin && typeof bin.bytes === "number" && bin.bytes > 0) {
  size = bin.bytes;
}
if (size === undefined && item.json && item.json.bytes !== undefined && item.json.bytes !== null) {
  const n = Number(item.json.bytes);
  if (Number.isFinite(n) && n > 0) size = n;
}
if (size === undefined && item.json && typeof item.json.fileSize === "string") {
  const m = item.json.fileSize.match(/([\d.,]+)\s*(B|KB|MB|GB)?/i);
  if (m) {
    const val = Number(String(m[1]).replace(",", "."));
    const unit = (m[2] || "B").toUpperCase();
    const mult = unit === "GB" ? 1000000000 : unit === "MB" ? 1000000 : unit === "KB" ? 1000 : 1;
    if (Number.isFinite(val) && val > 0) size = Math.round(val * mult);
  }
}
if (size === undefined && bin && bin.data && typeof bin.data === "string") {
  size = Math.floor((bin.data.length * 3) / 4);
}

if (!size || !Number.isFinite(size)) {
  throw new Error("No se pudo determinar el tamano del video en bytes. Se descargo bien el fichero con yt-dlp?");
}

const mimeType = (item.json && item.json.mimeType) || (bin && bin.mimeType) || "video/mp4";

return [{ json: { size: Number(size), mimeType }, binary: item.binary }];

const MAX_INTENTOS = 30;

// Contador persistente, reiniciado en cada ejecución del workflow.
const staticData = $getWorkflowStaticData('global');
const execId = $execution && $execution.id ? $execution.id : 'manual';
if (staticData.execId !== execId) {
  staticData.execId = execId;
  staticData.intento = 0;
}
staticData.intento = (staticData.intento || 0) + 1;

const item = $input.first();
const state = item.json.state;
const intento = staticData.intento;

if (state !== 'ACTIVE' && intento >= MAX_INTENTOS) {
  throw new Error('Gemini no terminó de procesar el vídeo tras ' + MAX_INTENTOS + ' intentos (~' + (MAX_INTENTOS * 2) + ' s). Último estado: ' + state);
}

return [{ json: { ...item.json, intento, maxIntentos: MAX_INTENTOS } }];

const gem = $input.first().json;

let text = "";
const parts = gem && gem.candidates && gem.candidates[0]
  && gem.candidates[0].content && gem.candidates[0].content.parts;
if (Array.isArray(parts)) {
  text = parts.map(p => (p && p.text) ? p.text : "").join("");
}

if (!text) {
  const block = gem && gem.promptFeedback && gem.promptFeedback.blockReason;
  const finish = gem && gem.candidates && gem.candidates[0] && gem.candidates[0].finishReason;
  const rid = gem && gem.responseId;
  throw new Error("Gemini no devolvio contenido"
    + (block ? " (blockReason: " + block + ")" : "")
    + (finish ? " (finishReason: " + finish + ")" : "")
    + (rid ? " responseId=" + rid : "")
    + ". Revisa el contenido del video o los limites/cuota del modelo.");
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error("No se pudo parsear el JSON devuelto por Gemini: " + e.message + " | Texto recibido: " + String(text).slice(0, 500));
}

const origen = $("Normalizar URL").first().json;
const puntos = Array.isArray(parsed.puntos_clave) ? parsed.puntos_clave.map(String) : [];

const MAX_LEN = 2000;
function splitTexto(str) {
  const s = String(str === undefined || str === null ? "" : str);
  if (s.length <= MAX_LEN) return [s];
  const chunks = [];
  let rest = s;
  while (rest.length > MAX_LEN) {
    let cut = rest.lastIndexOf(" ", MAX_LEN);
    if (cut <= 0) cut = MAX_LEN;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).trimStart();
  }
  if (rest.length > 0) chunks.push(rest);
  return chunks;
}
function richText(str) {
  return splitTexto(str).map(c => ({ type: "text", text: { content: c } }));
}

const children = [];
children.push({ object: "block", type: "divider", divider: {} });
children.push({ object: "block", type: "heading_2", heading_2: { rich_text: richText("Resumen") } });
children.push({ object: "block", type: "paragraph", paragraph: { rich_text: richText(parsed.resumen || "") } });
children.push({ object: "block", type: "heading_2", heading_2: { rich_text: richText("Puntos clave") } });
for (const punto of puntos) {
  children.push({ object: "block", type: "bulleted_list_item", bulleted_list_item: { rich_text: richText(punto) } });
}
children.push({ object: "block", type: "heading_2", heading_2: { rich_text: richText("Enlace original") } });
const enlace = String(origen.url || "");
children.push({ object: "block", type: "paragraph", paragraph: { rich_text: [{ type: "text", text: { content: enlace, link: { url: enlace } } }] } });

return [{
  json: {
    url: origen.url,
    titulo: parsed.titulo,
    resumen: parsed.resumen,
    jobId: origen.jobId,
    callbackBaseUrl: origen.callbackBaseUrl,
    children
  }
}];

