const src = (wh && wh.body) ? wh.body : (wh || {});
let callbackBaseUrl = String($env.CALLBACK_BASE_URL || src.callbackBaseUrl || 'http://localhost:3333');
if (callbackBaseUrl.endsWith('/')) callbackBaseUrl = callbackBaseUrl.slice(0, -1);
const url = callbackBaseUrl + '/api/internal/reels/' + encodeURIComponent(src.jobId || 'desconocido') + '/status';

// Contrato exacto: { stage, status, message, notionPageUrl?, notionDatabaseUrl? }
const payload = { stage: 'recibido', status: 'running', message: 'Enlace recibido' };

try {
