const origen = $('Normalizar URL').first().json;
let callbackBaseUrl = String($env.CALLBACK_BASE_URL || origen.callbackBaseUrl || 'http://localhost:3333');
if (callbackBaseUrl.endsWith('/')) callbackBaseUrl = callbackBaseUrl.slice(0, -1);
const url = callbackBaseUrl + '/api/internal/reels/' + encodeURIComponent(origen.jobId || 'desconocido') + '/status';

const j = $json || {};
const err = j.error;
const pick = (v) => (v === undefined || v === null) ? '' : String(v);

let rawMessage = '';
let httpCode;
let retryAfterHeader;
const technicalParts = [];

if (typeof err === 'string') {
  rawMessage = err;
} else if (err && typeof err === 'object') {
  rawMessage = pick(err.message) || pick(err.description);
  httpCode = err.httpCode !== undefined ? err.httpCode
    : (err.statusCode !== undefined ? err.statusCode : (err.response && err.response.status));
  const headers = err.response && err.response.headers ? err.response.headers : undefined;
  if (headers) retryAfterHeader = headers['retry-after'] !== undefined ? headers['retry-after'] : headers['Retry-After'];
  if (err.description && pick(err.description) !== rawMessage) technicalParts.push(pick(err.description));
  if (err.reason) technicalParts.push(pick(err.reason));
  if (err.response && err.response.body !== undefined) {
    const body = err.response.body;
    technicalParts.push(typeof body === 'string' ? body : JSON.stringify(body));
  }
  if (err.stack) technicalParts.push(pick(err.stack));
}
if (!rawMessage) rawMessage = pick(j.message) || pick(j.description) || 'Error en el flujo de la reel';

const message = String(rawMessage).replace(/[\r\n"]+/g, ' ').slice(0, 300);
const technical = technicalParts.join(' | ').replace(/[\r\n]+/g, ' ').slice(0, 500);
const haystack = (String(rawMessage) + ' ' + technical + ' ' + pick(j.message) + ' ' + pick(j.description)).toLowerCase();

const ALLOWLIST = ['INVALID_LINK','VIDEO_UNAVAILABLE','DOWNLOAD_FAILED','UPLOAD_FAILED','CONTENT_BLOCKED','QUOTA_EXCEEDED','TIMEOUT','NOTION_ERROR','INTERNAL'];
let errorCode = pick(j.errorCode).toUpperCase();
if (!ALLOWLIST.includes(errorCode)) errorCode = '';

const stageHint = pick(j.failedStage).toLowerCase();
const VALID_STAGES = ['validando','descargando','subiendo','procesando','generando','guardando'];

if (!errorCode) {
  if (stageHint === 'guardando') {
    errorCode = 'NOTION_ERROR';
  } else if (/PROHIBITED_CONTENT|blockreason|no devolvi[oó] contenido/i.test(haystack)) {
    errorCode = 'CONTENT_BLOCKED';
  } else if (Number(httpCode) === 429 || /RESOURCE_EXHAUSTED|quota|too many requests/i.test(haystack)) {
    errorCode = 'QUOTA_EXCEEDED';
  } else if (/timeout|timed out|etimedout/i.test(haystack)) {
    errorCode = 'TIMEOUT';
  } else if (/notion/i.test(haystack)) {
    errorCode = 'NOTION_ERROR';
  } else if (stageHint === 'descargando') {
    errorCode = /private|unavailable|no longer available|deleted|removed|not available|does not exist|login required|sign in|age.?restricted/i.test(haystack)
      ? 'VIDEO_UNAVAILABLE'
      : 'DOWNLOAD_FAILED';
  } else if (stageHint === 'subiendo') {
    errorCode = 'UPLOAD_FAILED';
  } else {
    errorCode = 'INTERNAL';
  }
}

let stage = VALID_STAGES.includes(stageHint) ? stageHint : '';
if (!stage) {
  const STAGE_BY_CODE = {
    INVALID_LINK: 'validando',
    VIDEO_UNAVAILABLE: 'descargando',
    DOWNLOAD_FAILED: 'descargando',
    UPLOAD_FAILED: 'subiendo',
    CONTENT_BLOCKED: 'generando',
    QUOTA_EXCEEDED: 'generando',
    NOTION_ERROR: 'guardando',
  };
  stage = STAGE_BY_CODE[errorCode] || '';
}
if (!stage) {
  const fases = ['guardando','generando','procesando','subiendo','descargando','validando'];
  for (const f of fases) {
    try {
      $('Notificar estado: ' + f).first();
      stage = f;
      break;
    } catch (e) { /* fase no ejecutada */ }
  }
  if (!stage) stage = 'validando';
}

const META = {
  INVALID_LINK:      { retryable: false, action: 'choose_another' },
  VIDEO_UNAVAILABLE: { retryable: false, action: 'choose_another' },
  DOWNLOAD_FAILED:   { retryable: true,  action: 'retry' },
  UPLOAD_FAILED:     { retryable: true,  action: 'retry' },
  CONTENT_BLOCKED:   { retryable: false, action: 'choose_another' },
  QUOTA_EXCEEDED:    { retryable: true,  action: 'wait' },
  TIMEOUT:           { retryable: true,  action: 'retry' },
  NOTION_ERROR:      { retryable: true,  action: 'retry' },
  INTERNAL:          { retryable: false, action: 'contact' },
};
const meta = META[errorCode] || META.INTERNAL;

const payload = {
  stage,
  status: 'error',
  message,
  errorCode,
  retryable: meta.retryable,
  action: meta.action,
};
if (errorCode === 'QUOTA_EXCEEDED') {
  const ra = parseInt(retryAfterHeader, 10);
  payload.retryAfterSeconds = (Number.isFinite(ra) && ra > 0) ? ra : 60;
}
if (technical) payload.technical = technical;

let attempt;
let maxAttempts;
if (typeof j.attempt === 'number') attempt = j.attempt;
else if (typeof j.intento === 'number') attempt = j.intento;
if (typeof j.maxAttempts === 'number') maxAttempts = j.maxAttempts;
else if (typeof j.maxIntentos === 'number') maxAttempts = j.maxIntentos;
if (attempt === undefined || maxAttempts === undefined) {
  try {
    const c = $('Contar intento').first().json;
    if (attempt === undefined && typeof c.intento === 'number') attempt = c.intento;
    if (maxAttempts === undefined && typeof c.maxIntentos === 'number') maxAttempts = c.maxIntentos;
  } catch (e) { /* aun no habia contador */ }
}
if (attempt !== undefined) payload.attempt = attempt;
if (maxAttempts !== undefined) payload.maxAttempts = maxAttempts;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: {
      'Content-Type': 'application/json',
      'x-callback-secret': String($env.CALLBACK_SECRET || ''),
    },
    body: JSON.stringify(payload),
    timeout: 15000,
  });
} catch (e) { /* tolerante */ }

return items;
